export function canAdvanceGearItem(record: { status: string; usageHours: number },
                                   locker: { id: string } | null): boolean {
  if (record.status === "stashed") {
    return locker !== null;
  }
  if (record.status === "inspected") {
    return record.usageHours >= 1 && record.usageHours <= 2000;
  }
  if (record.status === "retired") {
    return false;
  }
  return false;
}
